// Make the agent's inputs safe and predictable before touching the database
const j = $json;

// card: "credit", "debit", or the last 4 digits. Never keep more than 4 digits.
const raw = String(j.card ?? '').toLowerCase();
let card = '';
if (raw.includes('credit')) card = 'credit';
else if (raw.includes('debit')) card = 'debit';
else {
  const digits = raw.replace(/\D/g, '');
  if (digits.length >= 4) card = digits.slice(-4);
}

// reason: turn the caller's words into one of four values
const r = String(j.reason ?? '').toLowerCase();
let reason = 'other';
if (/stol|theft|thief|rob/.test(r)) reason = 'stolen';
else if (/lost|lose|missing|misplac|can.?t find/.test(r)) reason = 'lost';
else if (/fraud|unauthori|recogni|scam|suspicious|hack|not (me|them|mine)|was ?n.?t (me|them)|were ?n.?t (me|them)|did ?n.?o?t (make|authori)|didn.?t make/.test(r)) reason = 'fraud';

// confirmed: only an explicit yes counts
const yesWords = ['yes', 'y', 'true', 'confirmed', '1'];
const confirmed = yesWords.includes(String(j.confirmed ?? '').trim().toLowerCase()) ? 'yes' : '';

return {
  json: {
    customer_id: String(j.customer_id ?? '').replace(/\D/g, ''),
    security_answer: String(j.security_answer ?? ''),
    card,
    reason,
    confirmed,
  },
};

// Turn the result into clear instructions for the agent
const j = $json;
const input = $('Clean inputs').item.json;

if (!j || !j.customer_id) {
  return { json: { result: 'NOT VERIFIED. The customer ID or security answer did not match. Do not take any action. Ask the caller to verify again.' } };
}

const list = v => (typeof v === 'string' ? JSON.parse(v) : v) || [];
const all = list(j.all_cards);
const target = list(j.target_before);
const updated = list(j.updated);
const name = k => `${k.type} card ending ${k.last4}`;
const cardsText = all.length ? all.map(k => `${name(k)} (${k.status})`).join(', ') : 'none';

let result;

if (updated.length) {
  // The card was blocked
  const k = updated[0];
  result = `DONE. The ${name(k)} is now blocked (status: ${k.status}). It can no longer be used, and it cannot be unblocked. In the same reply, tell the caller it is blocked, and then ask the next question: if this was for fraud, ask whether to create an urgent fraud ticket for the charges they did not make; otherwise, ask whether they would like a replacement card.`;} else if (target.length) {
  const k = target[0];
  if (k.status !== 'active') {
    // Already blocked, lost, or expired
    result = `NO ACTION NEEDED. The ${name(k)} is already ${k.status}, so it cannot be used. Tell the caller this.`;
  } else {
    // Found the card, but the caller hasn't confirmed yet
    result = `NOT DONE YET. Ask the caller to confirm: "Just to confirm, you want me to block your ${name(k)}? Once blocked, it can't be used again." Only if they clearly say yes, use block_card again with confirmed set to yes.`;
  }
} else if (input.card) {
  // The caller named a card that doesn't match
  result = `NO MATCHING CARD. No active card matches "${input.card}". The customer's cards are: ${cardsText}. Ask which card they mean.`;
} else {
  const active = all.filter(k => k.status === 'active');
  if (active.length > 1) {
    // More than one active card, and none was specified
    result = `WHICH CARD? The customer has more than one active card: ${active.map(name).join(' and ')}. Ask which one to block, then use block_card again with that card.`;
  } else {
    // No active cards at all
    result = `NO ACTIVE CARDS. The customer has no active card to block. Their cards are: ${cardsText}. Tell the caller this.`;
  }
}

return { json: { result } };
